import { StatusBar } from "react-native";
import { demos } from "./src/demos/catalog";
import { DemoScreen } from "./src/demos/DemoScreen";
import { HomeScreen } from "./src/home/HomeScreen";
import { lab } from "./src/lab/catalog";
import { LabScreen } from "./src/lab/LabScreen";
import { useNavigator } from "./src/navigation/useNavigator";
import { useTheme } from "./src/ui/useTheme";

const catalog = { demos: demos.map((d) => d.id), lab: lab.map((l) => l.id) };

export default function App() {
  const theme = useTheme();

  const { route, key, open, back } = useNavigator(catalog);

  const demo = route.screen === "demo" ? demos.find((d) => d.id === route.id) : undefined;

  const entry = route.screen === "lab" ? lab.find((l) => l.id === route.id) : undefined;

  return (
    <>
      <StatusBar barStyle={theme.dark ? "light-content" : "dark-content"} />

      {demo && back ? <DemoScreen key={key} demo={demo} onBack={back} /> : null}

      {entry && back ? <LabScreen key={key} entry={entry} onBack={back} /> : null}

      {route.screen === "home" ? (
        <HomeScreen key={key} section={route.section} open={open} />
      ) : null}
    </>
  );
}
